import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"عجیب توانائی کے تین قسم کے انتظامی عمل","description":"","frontmatter":{},"headers":[],"relativePath":"ur/56-奇异能量三类处置流程.md","filePath":"ur/56-奇异能量三类处置流程.md"}'),h={name:"ur/56-奇异能量三类处置流程.md"};function l(i,t,o,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="عجیب-توانائی-کے-تین-قسم-کے-انتظامی-عمل" tabindex="-1">عجیب توانائی کے تین قسم کے انتظامی عمل <a class="header-anchor" href="#عجیب-توانائی-کے-تین-قسم-کے-انتظامی-عمل" aria-label="Permalink to &quot;عجیب توانائی کے تین قسم کے انتظامی عمل&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>56</td></tr><tr><td>ماڈیول</td><td>نسلیں اور زندگی کی شکلیں</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>ترقی اور استعمال، ذخیرہ اور نگرانی، پاکیزگی اور خاتمہ، توانائی کا انتظام، معیاری عمل</td></tr></tbody></table><h2 id="_1-انتظامی-عمل-کے-عمومی-اصول" tabindex="-1">1. انتظامی عمل کے عمومی اصول <a class="header-anchor" href="#_1-انتظامی-عمل-کے-عمومی-اصول" aria-label="Permalink to &quot;1. انتظامی عمل کے عمومی اصول&quot;">​</a></h2><p>عجیب توانائی کا انتظام اینکر سمبیوسس تہذیب کی توانائی کی انتظامیہ کا بنیادی حصہ ہے۔ &quot;55-عجیب توانائی کی درجہ بندی اور خصوصیات&quot; کے خطرے کی تشخیص کے نتائج کے مطابق، عجیب توانائی کے انتظام کو تین معیاری عملوں میں تقسیم کیا گیا ہے: ترقی اور استعمال کی قسم، ذخیرہ اور نگرانی کی قسم، پاکیزگی اور خاتمہ کی قسم۔ تین عمل بالترتیب کم خطرے، درمیانے خطرے اور زیادہ خطرے کے تین درجات سے مطابقت رکھتے ہیں، استعمال سے لے کر کنٹرول اور پھر خاتمے تک ایک مکمل انتظامی نظام تشکیل دیتے ہیں۔</p><p>انتظامی عمل درج ذیل عمومی اصولوں پر عمل کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>اندرونی معنی</th></tr></thead><tbody><tr><td>سلامتی پہلے کا اصول</td><td>توانائی کے انتظام کا بنیادی مقصد سلامتی کو یقینی بنانا ہے، بے قابو توانائی کی وجہ سے ہونے والے نقصان کو روکنا</td></tr><tr><td>قدر کو زیادہ سے زیادہ کرنے کا اصول</td><td>سلامتی اور قابو کے دائرے میں، عجیب توانائی کی قدر کو زیادہ سے زیادہ استعمال کرنا</td></tr><tr><td>تناسب کا اصول</td><td>انتظامی اقدامات کی شدت عجیب توانائی کی خطرے کی سطح کے مطابق ہونی چاہیے</td></tr><tr><td>کم سے کم ماحولیاتی اثر کا اصول</td><td>انتظامی عمل میں ماحول پر اثر کو زیادہ سے زیادہ کم کرنا چاہیے، توانائی کی آلودگی کو روکنا</td></tr><tr><td>مکمل عمل کی نگرانی کا اصول</td><td>انتظامی عمل کی مکمل نگرانی کرنا، توانائی کی حالت کو حقیقی وقت میں سمجھنا، غیر معمولی صورتحال کا فوری جواب دینا</td></tr></tbody></table><h2 id="_2-پہلی-قسم-ترقی-اور-استعمال-کی-قسم-کا-انتظامی-عمل" tabindex="-1">2. پہلی قسم: ترقی اور استعمال کی قسم کا انتظامی عمل <a class="header-anchor" href="#_2-پہلی-قسم-ترقی-اور-استعمال-کی-قسم-کا-انتظامی-عمل" aria-label="Permalink to &quot;2. پہلی قسم: ترقی اور استعمال کی قسم کا انتظامی عمل&quot;">​</a></h2><p>ترقی اور استعمال کا انتظام اس عجیب توانائی پر لاگو ہوتا ہے جس کی شناخت اور تشخیص پہلی سطح (کم خطرہ) کے طور پر کی گئی ہو، یعنی توانائی کی شکل جس کی فطرت مستحکم ہو، سنکنرن نہ ہو، قابل استعمال ہو، اور ماحولیاتی اثر قابو میں ہو۔</p><h3 id="_1-انتظام-کا-مقصد" tabindex="-1">(1) انتظام کا مقصد <a class="header-anchor" href="#_1-انتظام-کا-مقصد" aria-label="Permalink to &quot;(1) انتظام کا مقصد&quot;">​</a></h3><p>عجیب توانائی کو تہذیب کے توانائی کے وسائل کے نظام میں شامل کرنا، محفوظ اور موثر ترقی اور استعمال کرنا، اور اسے سمبیوسس ارتقاء کو فروغ دینے والے فائدہ مند وسائل میں تبدیل کرنا۔</p><h3 id="_2-انتظامی-مراحل" tabindex="-1">(2) انتظامی مراحل <a class="header-anchor" href="#_2-انتظامی-مراحل" aria-label="Permalink to &quot;(2) انتظامی مراحل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>مرحلہ</th><th>نام</th><th>تفصیلی مواد</th><th>ذمہ دار ادارہ</th></tr></thead><tbody><tr><td>پہلا مرحلہ</td><td>توانائی کی شناخت</td><td>عجیب توانائی کی مکمل شناخت کرنا، اس کی قسم، خصوصیات، پاکیزگی، قابل استعمال قدر وغیرہ کے پیرامیٹرز کا تعین کرنا</td><td>توانائی انتظامی بیورو + شناخت ماہرین کی ٹیم</td></tr><tr><td>دوسرا مرحلہ</td><td>سلامتی کی تشخیص</td><td>عجیب توانائی کی ترقی اور استعمال کی سلامتی کا جائزہ لینا، بشمول استحکام، رد عمل، ماحولیاتی اثر وغیرہ</td><td>سلامتی تشخیص ماہرین کی ٹیم</td></tr><tr><td>تیسرا مرحلہ</td><td>استعمال کا منصوبہ</td><td>تفصیلی ترقی اور استعمال کا منصوبہ تیار کرنا، بشمول استعمال کا طریقہ، تکنیکی راستہ، سلامتی کے اقدامات، اقتصادی فائدے کا تجزیہ وغیرہ</td><td>توانائی انتظامی بیورو + ٹیکنالوجی تحقیق اور ترقی ادارہ</td></tr><tr><td>چوتھا مرحلہ</td><td>تجرباتی استعمال</td><td>قابو شدہ ماحول میں چھوٹے پیمانے پر تجرباتی استعمال کرنا، منصوبے کی عملداری اور سلامتی کی تصدیق کرنا</td><td>ٹیکنالوجی تحقیق اور ترقی ادارہ + سادھک</td></tr><tr><td>پانچواں مرحلہ</td><td>بڑے پیمانے پر توسیع</td><td>تجربہ کامیاب ہونے کے بعد، استعمال کے پیمانے کو بتدریج بڑھانا، عجیب توانائی کو معمول کے توانائی کے وسائل کے نظام میں شامل کرنا</td><td>توانائی انتظامی بیورو + وسائل انتظامی شعبہ</td></tr><tr><td>چھٹا مرحلہ</td><td>معیاری انتظام</td><td>عجیب توانائی کے نکالنے، ذخیرہ کرنے، نقل و حمل اور استعمال کے معیارات تیار کرنا، معیاری انتظامی نظام میں شامل کرنا</td><td>معیاری انتظامی ادارہ</td></tr><tr><td>ساتواں مرحلہ</td><td>مسلسل نگرانی</td><td>ترقی اور استعمال کے مکمل عمل کی مسلسل نگرانی کرنا، باقاعدگی سے سلامتی اور استعمال کی کارکردگی کا جائزہ لینا</td><td>توانائی نگرانی نیٹ ورک</td></tr></tbody></table><h3 id="_3-استعمال-کی-بنیادی-سمیتیں" tabindex="-1">(3) استعمال کی بنیادی سمیتیں <a class="header-anchor" href="#_3-استعمال-کی-بنیادی-سمیتیں" aria-label="Permalink to &quot;(3) استعمال کی بنیادی سمیتیں&quot;">​</a></h3><table tabindex="0"><thead><tr><th>استعمال کی سمت</th><th>قابل اطلاق توانائی کی قسم</th><th>تفصیلی استعمال</th></tr></thead><tbody><tr><td>سادھن کا وسیلہ</td><td>عنصری تبدیلی کی قسم، اصول سے ماخوذ قسم</td><td>اعلیٰ درجے کے سادھکوں کے لیے سادھن کے وسیلے کے طور پر، سادھن کی کارکردگی اور سطح کو بڑھانا</td></tr><tr><td>توانائی کی فراہمی</td><td>مستحکم قسم کی عجیب توانائی</td><td>معمول کی توانائی میں تبدیل کرنا، شہروں، بنیادی ڈھانچے اور شعبوں کی ترقی کے لیے توانائی فراہم کرنا</td></tr><tr><td>تکنیکی اطلاق</td><td>مقامی توانائی، وقتی توانائی</td><td>مقامی اصولوں کی تکنیک، بین الشعب مواصلت، وقت کی پسپائی اور دیگر اعلیٰ درجے کی تکنیکوں میں استعمال</td></tr><tr><td>طبی اطلاق</td><td>مقدس روشنی کی توانائی، ارادے کی طاقت</td><td>شدید زخموں کی شفا، منفی توانائی کی پاکیزگی، نفسیاتی علاج اور دیگر طبی شعبوں میں استعمال</td></tr><tr><td>ہتھیار اور سازوسامان</td><td>بنگنی بجلی، تیز ہوا</td><td>اعلیٰ درجے کے ہتھیاروں اور حفاظتی سازوسامان کی تیاری میں، تہذیب کی دفاعی صلاحیت کو بڑھانا</td></tr><tr><td>سائنسی تحقیق</td><td>مختلف قسم کی عجیب توانائیاں</td><td>بنیادی سائنس کی تحقیق، اصولوں کی تحقیق، کائناتی تحقیق اور دیگر علمی شعبوں میں استعمال</td></tr></tbody></table><h3 id="_4-استعمال-کی-سلامتی-کے-ضوابط" tabindex="-1">(4) استعمال کی سلامتی کے ضوابط <a class="header-anchor" href="#_4-استعمال-کی-سلامتی-کے-ضوابط" aria-label="Permalink to &quot;(4) استعمال کی سلامتی کے ضوابط&quot;">​</a></h3><ul><li>عجیب توانائی کا نکالنا پیشہ ور افراد کی رہنمائی میں ہونا چاہیے، ضروری حفاظتی سازوسامان اور ہنگامی سازوسامان سے لیس ہونا چاہیے۔</li><li>عجیب توانائی کا ذخیرہ کرنے کے لیے خصوصی توانائی ذخیرہ کرنے والے آلات کا استعمال کرنا چاہیے، ذخیرہ کرنے کی سہولیات میں توانائی کی پردہ اور سلامتی کے تحفظ کا نظام لگا ہوا ہونا چاہیے۔</li><li>عجیب توانائی کی نقل و حمل کے لیے خصوصی توانائی نقل و حمل کے برتنوں کا استعمال کرنا چاہیے، نقل و حمل کے راستے آبادی والے علاقوں اور ماحولیاتی حساس علاقوں سے بچنا چاہیے۔</li><li>عجیب توانائی کا استعمال آپریٹنگ طریقہ کار کی پابندی کرنا چاہیے، زیادہ استعمال یا قواعد خلاف ورزی ممنوع ہے۔</li><li>عجیب توانائی کے استعمال کے حادثات کے لیے ہنگامی منصوبہ بنانا، باقاعدگی سے ہنگامی مشقیں کرنا۔</li></ul><h2 id="_3-دوسری-قسم-ذخیرہ-اور-نگرانی-کی-قسم-کا-انتظامی-عمل" tabindex="-1">3. دوسری قسم: ذخیرہ اور نگرانی کی قسم کا انتظامی عمل <a class="header-anchor" href="#_3-دوسری-قسم-ذخیرہ-اور-نگرانی-کی-قسم-کا-انتظامی-عمل" aria-label="Permalink to &quot;3. دوسری قسم: ذخیرہ اور نگرانی کی قسم کا انتظامی عمل&quot;">​</a></h2><p>ذخیرہ اور نگرانی کا انتظام اس عجیب توانائی پر لاگو ہوتا ہے جس کی شناخت اور تشخیص دوسری سطح (درمیانہ خطرہ) کے طور پر کی گئی ہو، یعنی توانائی کی شکل جس کی فطرت نسبتاً فعال ہو، کچھ سنکنرن یا پھیلاؤ کی صلاحیت ہو، کنٹرول کی ضرورت ہو۔</p><h3 id="_1-انتظام-کا-مقصد-1" tabindex="-1">(1) انتظام کا مقصد <a class="header-anchor" href="#_1-انتظام-کا-مقصد-1" aria-label="Permalink to &quot;(1) انتظام کا مقصد&quot;">​</a></h3><p>سلامتی کو یقینی بنانے کے دائرے میں، عجیب توانائی کا ذخیرہ اور مسلسل نگرانی کرنا، اس کے پھیلاؤ یا نقصان کو روکنا؛ ساتھ ہی مسلسل تحقیق کرنا، محفوظ استعمال یا پاکیزگی کے امکانات کو دریافت کرنا۔</p><h3 id="_2-انتظامی-مراحل-1" tabindex="-1">(2) انتظامی مراحل <a class="header-anchor" href="#_2-انتظامی-مراحل-1" aria-label="Permalink to &quot;(2) انتظامی مراحل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>مرحلہ</th><th>نام</th><th>تفصیلی مواد</th><th>ذمہ دار ادارہ</th></tr></thead><tbody><tr><td>پہلا مرحلہ</td><td>توانائی کی روک تھام</td><td>خصوصی توانائی روک تھام کے آلات کا استعمال کرتے ہوئے عجیب توانائی کو ذخیرہ کرنا، اس کے پھیلاؤ کو روکنا</td><td>میدانی انتظامی ٹیم + ٹیکنالوجی ماہرین کی ٹیم</td></tr><tr><td>دوسرا مرحلہ</td><td>منتقلی اور نقل و حمل</td><td>ذخیرہ شدہ عجیب توانائی کو خصوصی توانائی ذخیرہ کرنے کی سہولت میں منتقل کرنا، نقل و حمل کے عمل کی مکمل نگرانی کرنا</td><td>توانائی انتظامی بیورو + سلامتی کے شعبہ</td></tr><tr><td>تیسرا مرحلہ</td><td>سہولت میں ذخیرہ</td><td>عجیب توانائی کو خصوصی ذخیرہ کرنے کی سہولت میں ذخیرہ کرنا، سہولت میں کثیر پرتوں والی توانائی کی پردہ، مقامی استحکام، سلامتی کے تحفظ کا نظام لگا ہوا ہو</td><td>توانائی ذخیرہ کرنے کی سہولت کا انتظامی ادارہ</td></tr><tr><td>چوتھا مرحلہ</td><td>مسلسل نگرانی</td><td>ذخیرہ شدہ عجیب توانائی کی 24 گھنٹے مسلسل نگرانی کرنا، توانائی کے اتار چڑھاؤ، درجہ حرارت، دباؤ وغیرہ کے پیرامیٹرز کی حقیقی وقت میں نگرانی کرنا</td><td>نگرانی ٹیم</td></tr><tr><td>پانچواں مرحلہ</td><td>باقاعدگی سے جانچ</td><td>باقاعدگی سے عجیب توانائی کی جانچ کرنا، اس کے استحکام اور خطرے کی سطح میں تبدیلی کا جائزہ لینا</td><td>شناخت ماہرین کی ٹیم</td></tr><tr><td>چھٹا مرحلہ</td><td>تحقیق اور دریافت</td><td>قابو شدہ حالات میں عجیب توانائی کی تحقیق کرنا، محفوظ استعمال یا پاکیزگی اور خاتمے کے تکنیکی راستے کو دریافت کرنا</td><td>سائنسی تحقیق ادارہ</td></tr><tr><td>ساتواں مرحلہ</td><td>قسم کی تبدیلی</td><td>تحقیق اور نگرانی کے نتائج کے مطابق، جب خطرہ پہلی سطح پر آجائے تو ترقی اور استعمال کی قسم میں تبدیل کرنا، جب خطرہ تیسری سطح پر بڑھے تو پاکیزگی اور خاتمے کی قسم میں تبدیل کرنا</td><td>توانائی انتظامی بیورو + عجیب زندگی کی عدالت</td></tr></tbody></table><h3 id="_3-ذخیرہ-کرنے-کی-سہولت-کے-معیارات" tabindex="-1">(3) ذخیرہ کرنے کی سہولت کے معیارات <a class="header-anchor" href="#_3-ذخیرہ-کرنے-کی-سہولت-کے-معیارات" aria-label="Permalink to &quot;(3) ذخیرہ کرنے کی سہولت کے معیارات&quot;">​</a></h3><ul><li><strong>مقام کا معیار</strong>: ذخیرہ کرنے کی سہولت کا مقام آبادی سے دور، ارضیاتی طور پر مستحکم، اور توانائی کے ماحول میں مستحکم علاقے میں ہونا چاہیے، ماحولیاتی تحفظ کے علاقوں اور اہم بنیادی ڈھانچے سے دور ہونا چاہیے۔</li><li><strong>تعمیر کا معیار</strong>: ذخیرہ کرنے کی سہولت کثیر پرتوں والے تحفظ کے ڈھانچے کو اپناتی ہے، بشمول جسمانی رکاوٹ، توانائی کی رکاوٹ، اور مقامی تالا تین پرتوں کے تحفظ، اس بات کو یقینی بنانا کہ توانائی نہ لیکے۔</li><li><strong>آلات کا معیار</strong>: اعلیٰ درستگی والے توانائی نگرانی کے آلات، خودکار روک تھام کا نظام، ہنگامی پاکیزگی کا نظام، بیک اپ توانائی کا نظام اور دیگر پیشہ ورانہ آلات سے لیس ہونا چاہیے۔</li><li><strong>انتظام کا معیار</strong>: داخلے اور نکلے کے سخت انتظام اور آپریٹنگ ضوابط کو نافذ کرنا، صرف مجاز پیشہ ور افراد ہی ذخیرہ کرنے والے علاقے میں داخل ہو سکتے ہیں۔</li><li><strong>ہنگامی معیار</strong>: مکمل ہنگامی منصوبے اور ہنگامی آلات سے لیس ہونا چاہیے، بشمول توانائی کے لیک کے ہنگامی انتظام، دھماکے کی ہنگامی ردعمل، افراد کی انخلاء کا منصوبہ وغیرہ۔</li></ul><h3 id="_4-طویل-مدتی-ذخیرہ-کا-انتظام" tabindex="-1">(4) طویل مدتی ذخیرہ کا انتظام <a class="header-anchor" href="#_4-طویل-مدتی-ذخیرہ-کا-انتظام" aria-label="Permalink to &quot;(4) طویل مدتی ذخیرہ کا انتظام&quot;">​</a></h3><p>جو عجیب توانائی طویل مدتی تحقیق کے بعد بھی محفوظ طریقے سے استعمال یا پاکیزگی اور خاتمہ نہیں کی جا سکتی، اس کے لیے طویل مدتی ذخیرہ کا انتظام لاگو کیا جاتا ہے:</p><ul><li>طویل مدتی ذخیرہ شدہ عجیب توانائی کی ہر سال ایک بار مکمل جانچ اور خطرے کی تشخیص کی جاتی ہے۔</li><li>ذخیرہ کرنے کی سہولت کی ہر پانچ سال میں ایک بار مکمل مرمت اور اپ گریڈ کی جاتی ہے، سہولت کی سلامتی اور قابل اعتمادی کو یقینی بنایا جاتا ہے۔</li><li>طویل مدتی ذخیرہ شدہ عجیب توانائی کی معلومات تہذیب کے توانائی کے وسائل کے آرکائیو میں شامل کی جاتی ہیں، باقاعدگی سے علمی تبادلے اور تحقیقی تعاون کیا جاتا ہے۔</li><li>اگر نئے تکنیکی ذرائع طویل مدتی ذخیرہ شدہ عجیب توانائی کو محفوظ طریقے سے استعمال یا پاکیزگی اور خاتمہ کر سکتے ہیں، تو فوری طور پر دوبارہ تشخیص اور انتظامی عمل شروع کرنا چاہیے۔</li></ul><h2 id="_4-تیسری-قسم-پاکیزگی-اور-خاتمے-کی-قسم-کا-انتظامی-عمل" tabindex="-1">4. تیسری قسم: پاکیزگی اور خاتمے کی قسم کا انتظامی عمل <a class="header-anchor" href="#_4-تیسری-قسم-پاکیزگی-اور-خاتمے-کی-قسم-کا-انتظامی-عمل" aria-label="Permalink to &quot;4. تیسری قسم: پاکیزگی اور خاتمے کی قسم کا انتظامی عمل&quot;">​</a></h2><p>پاکیزگی اور خاتمے کا انتظام اس عجیب توانائی پر لاگو ہوتا ہے جس کی شناخت اور تشخیص تیسری سطح (زیادہ خطرہ) کے طور پر کی گئی ہو، یعنی توانائی کی شکل جس میں مضبوط سنکنرن/نگلنے کی صلاحیت/متعدی ہو، بے قابو ہو، اور ماحولیاتی نقصان شدید ہو۔ چوتھی سطح (انتہائی زیادہ خطرہ) کی عجیب توانائی کے لیے ہنگامی خاتمے کا عمل لاگو ہوتا ہے۔</p><h3 id="_1-انتظام-کا-مقصد-2" tabindex="-1">(1) انتظام کا مقصد <a class="header-anchor" href="#_1-انتظام-کا-مقصد-2" aria-label="Permalink to &quot;(1) انتظام کا مقصد&quot;">​</a></h3><p>پاکیزگی یا خاتمے کے ذریعے، عجیب توانائی کی خطرناکیت کو ختم کرنا، اسے غیر نقصان دہ بنیادی توانائی میں تبدیل کرنا یا مکمل طور پر ختم کرنا، تہذیب اور ماحول کی سلامتی کو یقینی بنانا۔</p><h3 id="_2-انتظامی-طریقے" tabindex="-1">(2) انتظامی طریقے <a class="header-anchor" href="#_2-انتظامی-طریقے" aria-label="Permalink to &quot;(2) انتظامی طریقے&quot;">​</a></h3><p>پاکیزگی اور خاتمے کا انتظام دو طریقوں میں تقسیم کیا جاتا ہے، عجیب توانائی کی مخصوص صورتحال کے مطابق منتخب کیا جاتا ہے:</p><table tabindex="0"><thead><tr><th>طریقہ</th><th>نام</th><th>قابل اطلاق صورتحال</th><th>تفصیلی طریقہ</th></tr></thead><tbody><tr><td>طریقہ ایک</td><td>توانائی کی پاکیزگی</td><td>وہ عجیب توانائی جو پاک کی جا سکتی ہے اور پاک کرنے کے بعد قابل استعمال ہو</td><td>مقدس روشنی کی توانائی، ارادے کی طاقت اور دیگر پاکیزگی والی توانائیوں کا استعمال کرنا، یا خصوصی پاکیزگی کے آلات اور منتر، عجیب توانائی کے خطرناک خصوصیات کو پاک کر کے ہٹانا، اسے غیر نقصان دہ قابل استعمال معمول کی توانائی میں تبدیل کرنا</td></tr><tr><td>طریقہ دو</td><td>توانائی کا خاتمہ</td><td>وہ عجیب توانائی جو پاک نہیں کی جا سکتی یا جس کی پاکیزگی کا خطرہ بہت زیادہ ہو</td><td>خصوصی خاتمے کے آلات یا منتر کا استعمال کرنا، عجیب توانائی کو بنیادی ذرات یا خالی جگہ میں تقسیم کرنا، مکمل طور پر اس کے وجود اور خطرناکیت کو ختم کرنا</td></tr></tbody></table><h3 id="_3-انتظامی-مراحل" tabindex="-1">(3) انتظامی مراحل <a class="header-anchor" href="#_3-انتظامی-مراحل" aria-label="Permalink to &quot;(3) انتظامی مراحل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>مرحلہ</th><th>نام</th><th>تفصیلی مواد</th><th>ذمہ دار ادارہ</th></tr></thead><tbody><tr><td>پہلا مرحلہ</td><td>انتظام کی منظوری</td><td>زیادہ خطرہ والی عجیب توانائی کی پاکیزگی اور خاتمے کے لیے توانائی انتظامی بیورو اور عجیب زندگی کی عدالت کی مشترکہ منظوری ضروری ہے؛ انتہائی زیادہ خطرہ کے لیے پہلے انتظام کر کے بعد منظوری پوری کی جا سکتی ہے</td><td>توانائی انتظامی بیورو + عجیب زندگی کی عدالت</td></tr><tr><td>دوسرا مرحلہ</td><td>منصوبہ تیار کرنا</td><td>تفصیلی پاکیزگی اور خاتمے کا منصوبہ تیار کرنا، بشمول انتظام کا طریقہ، تکنیکی ذرائع، سلامتی کے اقدامات، ہنگامی منصوبہ، ماحولیاتی اثر کا جائزہ وغیرہ</td><td>ٹیکنالوجی ماہرین کی ٹیم + سلامتی تشخیص ماہرین کی ٹیم</td></tr><tr><td>تیسرا مرحلہ</td><td>سلامتی کی تنہائی</td><td>عجیب توانائی کو خصوصی پاکیزگی اور خاتمے کی سہولت میں منتقل کرنا، سہولت میں سب سے اوپر درجے کی سلامتی کے تحفظ اور توانائی روک تھام کے آلات لگے ہوئے ہوں</td><td>میدانی انتظامی ٹیم</td></tr><tr><td>چوتھا مرحلہ</td><td>پاکیزگی اور خاتمہ</td><td>منصوبے کے مطابق پاکیزگی اور خاتمہ کو نافذ کرنا، عمل کی مکمل نگرانی کرنا، جیسے ہی غیر معمولی صورتحال پیش آئے فوری طور پر ہنگامی منصوبہ شروع کرنا</td><td>ٹیکنالوجی ماہرین کی ٹیم + اعلیٰ درجے کے سادھک</td></tr><tr><td>پانچواں مرحلہ</td><td>پیداوار کا انتظام</td><td>پاکیزگی اور خاتمے سے پیدا ہونے والی توانائی اور مادے کی جانچ کرنا، قابل استعمال کو وسائل کے ذخیرے میں شامل کرنا، غیر نقصان دہ کو قدرتی طور پر خارج کرنا، نقصان دہ کا محفوظ انتظام کرنا</td><td>وسائل انتظامی ادارہ + ماحولیاتی شعبہ</td></tr><tr><td>چھٹا مرحلہ</td><td>ماحولیاتی بحالی</td><td>انتظامی عمل میں متاثرہ ماحول کی بحالی کرنا، ماحولیاتی اور توانائی کے توازن کو بحال کرنا</td><td>ماحولیاتی شعبہ</td></tr><tr><td>ساتواں مرحلہ</td><td>دستاویزات کا آرکائیو</td><td>انتظامی مکمل عمل کے ریکارڈ، ڈیٹا، رپورٹس کو منظم کر کے آرکائیو کرنا، مکمل انتظامی آرکائیو بنانا</td><td>توانائی انتظامی بیورو</td></tr></tbody></table><h3 id="_4-ہنگامی-خاتمے-کا-عمل" tabindex="-1">(4) ہنگامی خاتمے کا عمل <a class="header-anchor" href="#_4-ہنگامی-خاتمے-کا-عمل" aria-label="Permalink to &quot;(4) ہنگامی خاتمے کا عمل&quot;">​</a></h3><p>چوتھی سطح (انتہائی زیادہ خطرہ) کی عجیب توانائی، یعنی کائناتی تباہی کی طاقت والی، اصولوں کی سطح کا خطرہ، بے قابو، اور براہ راست تہذیب کی بقا کو خطرہ میں ڈالنے والی عجیب توانائی کے لیے، ہنگامی خاتمے کا عمل لاگو ہوتا ہے:</p><ol><li>میدان میں سب سے اوپر درجے کا ذمہ دار براہ راست ہنگامی خاتمہ شروع کرنے کا حکم دے سکتا ہے، پہلے منظوری کی ضرورت نہیں، لیکن انتظام کے بعد 24 گھنٹے کے اندر توانائی انتظامی بیورو اور عجیب زندگی کی عدالت کو رپورٹ کرنا ضروری ہے۔</li><li>ہنگامی خاتمے میں تہذیب کے سب سے اوپر درجے کی طاقت اور توانائی کے وسائل استعمال کیے جا سکتے ہیں، بشمول شعبوں کے سب سے طاقتور افراد کی مشترکہ کارروائی اور اینکر توانائی کا مرکزی استعمال۔</li><li>ہنگامی خاتمے کا ترجیحی مقصد خطرہ کو ختم کرنا، زندگی اور تہذیب کی سلامتی کی حفاظت کرنا ہے، توانائی کی بازیافت اور استعمال کی تلاش نہیں کی جاتی۔</li><li>ہنگامی خاتمے کے بعد مکمل ماحولیاتی جائزہ اور بحالی کرنی چاہیے، ثانوی آفات اور توانائی کی باقیات کو روکنا۔</li><li>ہنگامی خاتمے کے کیسز کی بعد میں جائزہ اور تجزیہ کرنا ضروری ہے، تجربات اور سبق حاصل کرنا، انتباہ اور انتظامی طریقہ کار کو بہتر بنانا۔</li></ol><h3 id="_5-بنیادی-پاکیزگی-اور-خاتمے-کی-ٹیکنالوجیز" tabindex="-1">(5) بنیادی پاکیزگی اور خاتمے کی ٹیکنالوجیز <a class="header-anchor" href="#_5-بنیادی-پاکیزگی-اور-خاتمے-کی-ٹیکنالوجیز" aria-label="Permalink to &quot;(5) بنیادی پاکیزگی اور خاتمے کی ٹیکنالوجیز&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ٹیکنالوجی کا نام</th><th>اصول</th><th>قابل اطلاق توانائی کی قسم</th></tr></thead><tbody><tr><td>مقدس روشنی پاکیزگی کا منتر</td><td>مقدس روشنی کی توانائی کی پاکیزگی کی صلاحیت کا استعمال کرنا، تاریک اور منفی توانائی کو بے اثر اور ختم کرنا</td><td>گہرائی کی توانائی، لعنت کی طاقت، موت کا پانی</td></tr><tr><td>ارادے کی طاقت پاکیزگی کا دائرہ</td><td>اجتماعی ارادے کی طاقت کا استعمال کرتے ہوئے پاکیزگی کا دائرہ بنانا، نرمی سے غیر معمولی توانائی کو پاک کرنا</td><td>شعور کی پروجیکشن کی قسم، ہلکی سنکنرن کی قسم</td></tr><tr><td>توانائی کے مقابلے کا طریقہ</td><td>عجیب توانائی کی صلاحیت کے مخالف صلاحیت والی توانائی کا استعمال کرتے ہوئے مقابلہ کرنا، ایک دوسرے کو ختم کرنا</td><td>عنصری تبدیلی کی قسم، مخالف صلاحیت کی توانائی</td></tr><tr><td>اصول خاتمے کا منتر</td><td>مقامی یا وقتی اصولوں کو بلانا، عجیب توانائی کو دوسری جگہ بھیجنا یا اس کے زوال کو تیز کرنا</td><td>اصول سے ماخوذ قسم، زیادہ ارتکاز والی توانائی</td></tr><tr><td>اینکر خاتمے کا دائرہ</td><td>اینکر توانائی کی اصلی صلاحیت کا استعمال کرنا، عجیب توانائی کو تقسیم کر کے کائناتی اصل میں واپس بھیجنا</td><td>مختلف قسم کی زیادہ خطرہ والی عجیب توانائیاں</td></tr><tr><td>مکینیکل خاتمے کا آلہ</td><td>اعلیٰ ٹیکنالوجی والے توانائی خاتمے کے آلے کا استعمال کرنا، جسمانی ذرائع سے توانائی کے ڈھانچے کو تقسیم کرنا</td><td>مستحکم قسم، جسمانی طور پر قابل عمل توانائی</td></tr></tbody></table><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>عجیب توانائی کے تین قسم کے انتظامی عمل اینکر سمبیوسس تہذیب کی توانائی کی انتظامیہ کا معیاری آپریٹنگ نظام ہے۔ ترقی اور استعمال کی قدر کی تبدیلی سے، ذخیرہ اور نگرانی کے محتاط کنٹرول تک، اور پھر پاکیزگی اور خاتمے کے محفوظ خاتمے تک، تین عمل مکمل توانائی خطرے کے ردعمل کا سلسلہ بناتے ہیں، جو نہ صرف عجیب توانائی کی ممکنہ قدر کو مکمل طور پر نکالتا ہے، بلکہ تہذیب کی سلامتی کی بنیاد کو مضبوطی سے بھی رکھتا ہے، &quot;استعمال اور کنٹرول دونوں یکساں اہمیت رکھتے ہیں، ترقی اور سلامتی دونوں کو یکجا غور کیا جاتا ہے&quot; کے توانائی انتظامی مقصد کو حاصل کرتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>55-عجیب توانائی کی درجہ بندی اور خصوصیات</li><li>54-عجیب زندگی کے تین قسم کے انتظامی عمل</li><li>15-توانائی کے چکر اور تبدیلی کے اصول</li><li>65-توانائی کا معیاری بنانا اور پیمائش</li></ul>',45)])])}const c=d(h,[["render",l]]);export{u as __pageData,c as default};
